<script>
function externalPaymentSchedule(startingGross, startingRate, startingApplied, startingType) {
    const defaultChannel = <?php echo json_encode($channels->first()?->id, 15, 512) ?>;
    const defaultRow = () => ({ month: new Date().toISOString().slice(0, 7), week: 1, channel: defaultChannel || '', amount: 0 });
    return { gross: Number(startingGross || 0), rate: Number(startingRate || 0), tdsApplied: Boolean(startingApplied), paymentType: startingType, rows: [defaultRow()], message: '',
        get tdsAmount() { return this.tdsApplied ? Math.round(this.gross * Number(this.rate || 0)) / 100 : 0; }, get netPayable() { return Math.round((this.gross - this.tdsAmount) * 100) / 100; }, get scheduledTotal() { return Math.round(this.rows.reduce((total, row) => total + Number(row.amount || 0), 0) * 100) / 100; }, get isReady() { return this.gross > 0 && this.rows.length > 0 && Math.abs(this.scheduledTotal - this.netPayable) < 0.01; },
        format(value) { return Number(value || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }, addRow() { this.rows.push(defaultRow()); }, removeRow(index) { this.rows.splice(index, 1); },
        init() { this.$watch('paymentType', value => { if (value === 'full') this.rows = [this.rows[0] || defaultRow()]; if (value === 'partial' && this.rows.length === 1) this.rows.push(defaultRow()); this.syncFull(); }); this.$watch('netPayable', () => this.syncFull()); this.syncFull(); }, syncFull() { if (this.paymentType === 'full' && this.rows[0]) this.rows[0].amount = this.netPayable; },
    };
}
</script>
